/*
 * A085904  Numbers k such that k, k+1 and k+2 are 7-smooth, i.e., all prime
 *          divisors <= 7 (A002473).
 * https://oeis.org/A085904
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, fini, full
 * Formula:   a(n) is the nth integer k for which k, k+1, and k+2 * are all
 *            7‑smooth (primes ≤ 7). The sequence is generated by *
 *            brute‑force search
 * Range:     u8 n <= 10, u16 n <= 10, u32 n <= 10, u64 n <= 10, u128 n <= 10,
 *            big any n
 * Helpers:   is_smooth_7
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include "../utils/is_smooth_7.h"

/* cache of computed terms */
static seq_t *cached_terms = NULL;
static idx_t terms_len  = 0;   /* number of terms stored */
static idx_t terms_cap  = 0;   /* capacity of cache */
static idx_t next_search = 1;  /* next k to test */

/* grow cache if needed */
static void ensure_terms_cap(idx_t need)
{
    if (need <= terms_cap) return;
    idx_t new_cap = terms_cap ? terms_cap << 1 : 16;
    while (new_cap < need) new_cap <<= 1;
    seq_t *new_arr = (seq_t *)realloc(cached_terms, new_cap * sizeof(seq_t));
    cached_terms = new_arr;
    terms_cap    = new_cap;
}

/* main function required by the framework */
seq_t a(idx_t n)
{
    /* already have required term? */
    if (terms_len >= n) return cached_terms[n - 1];

    /* ensure cache can grow during search */
    ensure_terms_cap(n);

    /* search until we find n terms */
    for (idx_t k = next_search; ; ++k)
    {
        uint64_t v = (uint64_t)k;
        if (is_smooth_7(v) && is_smooth_7(v + 1ULL) && is_smooth_7(v + 2ULL))
        {
            /* store term */
            cached_terms[terms_len++] = (seq_t)v;
            if (terms_len == n)
            {
                next_search = k + 1;  /* continue from the next number on next call */
                return cached_terms[n - 1];
            }
        }
        /* avoid infinite loop if term does not exist (sequence finite) */
        /* optional safety: break if k becomes too large (e.g., > 2^63-3) */
        if (k == ((idx_t)-3))  /* prevents overflow of k+2 */
            break;
    }

    /* If sequence is finite and n is beyond the last known term,
     * return the largest known term (or 0 if none).  This behaviour
     * is arbitrary but keeps the function defined for all n. */
    return terms_len ? cached_terms[terms_len - 1] : (seq_t)0;
}
